import {hasWangReading,wangPage,wangOverviewPage,wangClosingPage} from './wang.js?v=20261012-tian-depth1';
import {acceptancePage,acceptanceConceptPage,initAcceptance} from './acceptance.js?v=20261012-ren-depth1';
import {initTianVisuals} from './tian-visuals.js?v=20261012-tian-depth1';
import {hasDaoReading,daoReadingToc,daoReadingBody,daoReadingSources,daoReadingPractice} from './dao-reading.js?v=20261012-tian-depth1';
import {beginNavigation,finishNavigation} from './navigation.js?v=20261011-return1';
import {initReadingUI} from './reading-ui.js?v=20261011-wang1';
import {home,initHome} from './home.js?v=20261011-video1';
import {elements} from './elements.js?v=20261012-ren-depth1';
import {paths,notes,extraNodes,exercises} from './data.js?v=20261012-tian-depth1';
import {essayPage} from './essay.js?v=20261011-author-essay1';
import {becomingPage,initBecoming,ninePracticePage,initNinePractice,becomingElementPage,becomingReadingPage} from './becoming.js?v=20261012-ren-depth1';
import {mountArt,diagram} from './art.js';
import {selfLayers,selfElements,knowingPage,selfLayerPage,selfElementPage,initKnowing} from './knowing.js?v=20261012-ren-depth1';
const $=s=>document.querySelector(s), main=$('#main');
const arrow='<span aria-hidden="true">↗</span>';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(href,label,cls='text-link')=>`<a class="${cls}" href="#/${href}">${label} ${arrow}</a>`;
const button=(href,label)=>link(href,label,'button');
const indexed=paths.flatMap(p=>p.groups.flatMap(g=>g.items.map(([id,name,summary])=>({id,name,summary,path:p.id,group:g.name,groupId:g.id}))));
const lookup=id=>indexed.find(x=>x.id===id)||extraNodes.find(x=>x.id===id)||({aspects:{id:'aspects',name:'三个“我”',path:'ren',group:'认识自己',summary:'外在角色我 · 内在角色我 · 内在意识我'},natures:{id:'natures',name:'三性',path:'ren',group:'认识自己的实践',summary:'兽性 · 人性 · 神性'},awakenings:{id:'awakenings',name:'三觉',path:'ren',group:'认识自己的实践',summary:'觉醒 · 觉知 · 觉悟'}}[id]);
const groupHome={knowing:'knowing',acceptance:'acceptance',becoming:'becoming'};
const hrefFor=id=>id==='knowing'||id==='aspects'?'knowing':[...selfLayers,...selfElements].some(x=>x.id===id)?`knowing/${id}`:elements.some(e=>e.id===id)?`becoming/${id}`:['consciousness','template','reality'].includes(id)?`becoming?layer=${id}`:id==='seven'?'becoming':id==='layout'?'layout':`concept/${id}`;
const sectionLabel=(n,text)=>`<div class="section-label"><span>${n}</span><span>${text}</span></div>`;
let cleanup=()=>{},currentRoute='',revealObserver;
const breadcrumbs=items=>`<nav class="breadcrumbs" aria-label="当前位置"><a href="#/">首页</a>${items.map(([label,route])=>`<span aria-hidden="true">/</span>${route?`<a href="#/${route}">${label}</a>`:`<span aria-current="page">${label}</span>`}`).join('')}</nav>`;
const trail=(node)=>{let p=node.path?paths.find(p=>p.id===node.path):paths[2];let items=[[p.name,p.id]];if(node.group)items.push([node.group,groupHome[node.groupId]||`map?focus=${node.groupId}`]);if(node.parent){items.push(['王之三力','map?focus=powers'],[lookup(node.parent).name,hrefFor(node.parent)]);}items.push([node.name,null]);return items;};
const pageHead=(eyebrow,title,desc,cls='')=>`<div class="page-heading ${cls}"><p class="eyebrow">${eyebrow}</p><h1>${title}</h1>${desc?`<p class="page-intro">${desc}</p>`:''}</div>`;

function start(){return `<div class="page-shell">${breadcrumbs([['从这里开始']])}${pageHead('AN OPEN INVITATION','从这里开始。','三道哲学是《哲人王》的学习与实践手册。<br>沿着世界观、人生观与价值观，走向亲身的理解与创造。')}<div class="start-intro"><p>你不需要一次读完全部内容。<br>先找到一个与你有关的问题，<br>让理解与生活相互回应。</p><div>${diagram('wang')}<span class="micro">求真与创造，在实践中相互贯通</span></div></div><div class="reading-path">${[['01','先看见整体','三道总论','理解为什么从求真出发，走向创造自己、改变世界与成就他人。','essay','约 30 分钟'],['02','找到思想的位置','三道全图','从三道、九条主干，逐步展开概念，理解它们彼此如何联系。','map','按兴趣探索'],['03','带回一件真实的事','日用三步','把看清、选择与成为，写成今天的一次具体回应。','practice','约 5 分钟']].map(([n,k,title,desc,url,time])=>`<a class="reading-stop reveal" href="#/${url}"><span class="reading-number">${n}</span><div><span class="eyebrow">${k}</span><h2>${title}</h2><p>${desc}</p></div><span class="micro">${time}</span><span class="row-arrow">↗</span></a>`).join('')}</div><section class="book-note"><span class="eyebrow">《哲人王》与三道哲学</span><h2>让思想，有一条可以走的路。</h2><p>《哲人王》提出看见真理、承担创造与成就他人的方向。三道哲学把背后的世界观、人生观与价值观展开为可学习的结构，并将它们带入体验、选择和行动。</p><p>阅读天道时，理解命题的定义与思想来源；进入人道时，回到真实的自身体验；走向王道时，让认识接受共同生活与创造的检验。</p>${link('essay','进入三道总论')}</section></div>`;}

function overview(id){const p=paths.find(p=>p.id===id);return `<div class="page-shell">${breadcrumbs([[p.name]])}<div class="overview-head">${pageHead(`${p.number} / ${p.en}`,`${p.name}<span class="heading-separator">/</span>${p.verb}`,p.intro)}${diagram(id)}</div><div class="overview-question"><span>这一道的追问</span><p>${p.question}</p></div>${p.groups.map((g,i)=>`<section class="overview-group reveal"><div><span class="eyebrow">${p.number}.${i+1}</span>${groupHome[g.id]?`<a class="overview-knowing-link" href="#/${groupHome[g.id]}"><h2>${g.name}</h2><p>${g.desc}</p></a>`:`<h2>${g.name}</h2><p>${g.desc}</p>`}</div><div class="concept-list">${g.items.map(([key,title,desc])=>`<a href="#/${hrefFor(key)}"><h3>${title}</h3><p>${desc}</p>${arrow}</a>`).join('')}</div></section>`).join('')}${id==='tian'?'<p class="philosophy-note">天道中的本源、全时、蓝图与生成，以三道哲学的世界观展开。阅读时，请把哲学命题、思想来源、个人体验与可检验的事实分别理解。</p>':''}<div class="next-route"><p>${id==='tian'?'既然世界具有这样的结构，那么身处其中的“我”，究竟是谁？':id==='ren'?'当自身的选择进入行动，我们开始改变共同生活的条件。':'在成就他人的实践中，检验对世界的理解，深化领导的智慧。'}</p>${button(id==='tian'?'ren':id==='ren'?'wang':'tian',id==='tian'?'走向人道':id==='ren'?'走向王道':'回到天道')}</div></div>`;}

const mapChildren=id=>[...extraNodes.filter(n=>n.parent===id),...elements.filter(n=>n.layer===id),...selfElements.filter(n=>n.layer===id)];

function mapPage(focus){return `<div class="page-shell map-shell">${breadcrumbs([['三道全图']])}${pageHead('THE ATLAS OF TRIA TAO','<span class="nowrap">一张图，</span><span class="nowrap">看见三道。</span>','从整体找到位置，再沿着分支深入。三道相互贯通，学习可以从任何一处开始。')}<div class="map-toolbar"><div class="filter-tabs" role="group" aria-label="筛选三道"><button class="active" data-map-filter="all" aria-pressed="true">全部</button>${paths.map(p=>`<button data-map-filter="${p.id}" aria-pressed="false">${p.name}</button>`).join('')}</div><div><button class="plain-button" data-expand="yes">全部展开</button><span aria-hidden="true"> / </span><button class="plain-button" data-expand="no">收起分支</button></div></div><div class="atlas">${paths.map(p=>`<section class="atlas-column" data-path="${p.id}"><a class="atlas-root" href="#/${p.id}"><span class="eyebrow">${p.number} / ${p.en}</span><h2>${p.name}<span>${p.verb}</span></h2>${diagram(p.id)}</a>${p.groups.map(g=>`<details class="atlas-group" id="map-${g.id}" ${!focus||focus===g.id?'open':''}><summary><span>${groupHome[g.id]?`<a href="#/${groupHome[g.id]}">${g.name}</a>`:g.name}</span><span class="summary-sign">+</span></summary><div class="atlas-leaves">${g.items.map(([key,name,desc])=>`<div class="atlas-leaf${mapChildren(key).length?' atlas-branch':''}"><a href="#/${hrefFor(key)}"><span>${name}</span>${mapChildren(key).length?'':`<small>${desc}</small>`}${arrow}</a>${mapChildren(key).length?`<div class="sub-leaves">${mapChildren(key).map(n=>link(hrefFor(n.id),n.name,'')).join('')}</div>`:''}</div>`).join('')}</div></details>`).join('')}</section>`).join('')}</div><div class="atlas-footer"><p>天道追问真实，人道展开选择，王道使创造进入共同世界。<br>实践带来的新认识，又不断回到求真与自身的转化。</p>${link('practice','把思想带回生活')}</div></div>`;}

const markdown=text=>text.split('\n\n').map(part=>{if(part.startsWith('# '))return '';if(part.startsWith('## '))return `<h2 id="chapter-${part.slice(3).split('：')[0]}">${esc(part.slice(3))}</h2>`;const format=s=>esc(s).replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>');if(part.startsWith('> '))return `<blockquote>${format(part.slice(2))}</blockquote>`;return `<p>${format(part)}</p>`;}).join('');

function conceptPage(id){if(hasWangReading(id))return wangPage(id);if(['cognitive','emotional','existential'].includes(id))return acceptanceConceptPage(id);if(id==='aspects')return knowingPage();if(selfLayers.some(x=>x.id===id))return selfLayerPage(id);if(selfElements.some(x=>x.id===id))return selfElementPage(id);if(['seven','consciousness','template','reality'].includes(id))return becomingPage();const n=lookup(id);if(!n)return notFound();const def=notes[id]||[n.text,'',n.question],expanded=hasDaoReading(id);return `<div class="page-shell${expanded?' dao-reading':''}">${breadcrumbs(trail(n))}${pageHead(`${(n.path||'wang').toUpperCase()} / ${n.group||lookup(n.parent)?.name||''}`,n.name,n.summary)}<div class="article-layout"><aside class="article-toc"><span class="eyebrow">在三道中的位置</span><p>${(paths.find(p=>p.id===n.path)||paths[2]).name} / ${n.group||'王之三力'}</p>${expanded?daoReadingToc(id):''}${link('map','查看完整结构')}${n.path==='ren'?link('awareness','进入觉察训练'):''}</aside><article class="prose"><h2${expanded?` id="dao-${id}-definition"`:""}>理解${n.name}</h2><p>${def[0]}</p>${def[1]?`<p>${def[1]}</p>`:''}${['strategy','system','people'].includes(id)?`<div class="related-branches">${extraNodes.filter(x=>x.parent===id).map(x=>`<a href="#/${hrefFor(x.id)}"><h3>${x.name} ${arrow}</h3><p>${x.summary}</p></a>`).join('')}</div>`:''}${expanded?daoReadingBody(id):''}<div class="question-callout"><span class="eyebrow">带回生活</span><h3>${def[2]}</h3>${link('practice','记录一次选择')}</div><h2${expanded?` id="dao-${id}-practice"`:""}>开始一次小的实践</h2><p>${expanded?daoReadingPractice(id):id==='people'?'选择一次真实的合作。先询问对方想发展什么、愿意承担什么，再明确一项由他自主决定的任务。一起约定目标、支持和回看结果的时间。':id==='strategy'?'选取一个反复出现的问题，分别写下已知事实、关键约束与未来假设。找到可以影响约束的一步行动，约定什么时候根据结果重新判断。':n.path==='tian'?'选择一段让你产生疑问的经验。写下确实发生的事情、自己的解释，以及仍不确定的部分。以这个概念重新观察一次，看看它打开了什么问题，又有哪些地方仍需要进一步追问。':'回到最近的一件小事。描述发生了什么，辨认其中的感受与判断，再回答上面的问题。选择一种愿意体现的品质，把它落实为今天可以做出的一次回应。'}</p>${expanded?daoReadingSources(id):''}${n.path==='tian'?'<p class="philosophy-note">本页阐释三道哲学的思想命题。个人体验与世界观的解释，需要和可检验的事实分别讨论。</p>':''}</article></div></div>`;}

function layoutPage(){return wangPage('layout');}
function practicePage(context){return `<div class="page-shell practice-page">${breadcrumbs([['实践'],['日用三步']])}${pageHead('A DAILY PRACTICE','看清 <span class="light-arrow">→</span> 选择 <span class="light-arrow">→</span> 成为','给自己几分钟，从一件正在发生的事开始。')}<div class="practice-workspace"><aside class="practice-guide"><span class="eyebrow">一次真实的选择</span><p>生命的意义在于——<br>通过体验，认识自己；<br>通过选择，创造自己。</p>${context==='layout'?'<div class="context-note">你从「布局」进入。<br>可以围绕未来的方向、今天的先手与需要保留的自由展开。</div>':''}<div class="save-explanation"><span class="status-dot"></span><p>记录仅保存在当前浏览器。<br>你可以随时导出或清空。</p></div><p class="micro" id="save-status" aria-live="polite">等待写下第一句</p>${link('awareness','先练习觉察')}</aside><form id="practice-form"><div class="practice-field"><span>01</span><label for="clarity">看清</label><p id="clarity-help">此刻发生了什么？我的感受、念头与判断是什么？</p><textarea id="clarity" name="clarity" aria-describedby="clarity-help" placeholder="先写事实，再写我的感受与解释……" rows="4"></textarea></div><div class="practice-field"><span>02</span><label for="choice">选择</label><p id="choice-help">我愿意以怎样的自己参与其中？我真正珍视什么？</p><textarea id="choice" name="choice" aria-describedby="choice-help" placeholder="在这件事中，我选择成为一个……的人。" rows="3"></textarea></div><div class="practice-field"><span>03</span><label for="action">成为</label><p id="action-help">今天什么表达或行动能体现这一选择？何时回看结果？</p><textarea id="action" name="action" aria-describedby="action-help" placeholder="我今天可以做的一步是……我会在……回看。" rows="3"></textarea></div><div class="practice-actions"><button type="submit" class="button">回看我的选择 <span>↗</span></button><button type="button" class="plain-button" id="export-practice">导出记录 ↓</button><button type="button" class="plain-button" id="clear-practice">清空</button></div><p id="practice-validation" role="alert"></p><div id="practice-summary" class="practice-summary" hidden></div></form></div></div>`;}

function awarenessPage(){return `<div class="page-shell">${breadcrumbs([['实践','practice'],['觉察训练']])}${pageHead('THE PRACTICE OF ATTENTION','先停一下。<br>看见正在发生的事。','觉察，从回到真实体验开始。选择一个入口，给自己片刻观察，然后把所见带入选择。')}<div class="awareness-layout"><div class="awareness-instrument"><div class="breathing-circle" aria-hidden="true"><span></span><span></span><span></span></div><p id="awareness-cue">感受脚下与自然的呼吸</p><button id="awareness-timer" class="button" data-state="idle">开始一分钟观察 <span>↗</span></button><p class="micro" id="timer-status" aria-live="polite">按自己的节奏，无需改变呼吸</p></div><div class="awareness-entries"><span class="eyebrow">七个觉察入口</span>${exercises.map(([title,body],i)=>`<details ${i===0?'open':''}><summary><span>${String(i+1).padStart(2,'0')}</span>${title}<span class="summary-sign">+</span></summary><p>${body}</p></details>`).join('')}</div></div><section class="awareness-after"><h2>练习之后，回到选择。</h2><p>用一句话描述观察到的体验，再分辨事实、感受与解释。注意力离开了，就再回来一次。持续练习，让辨认、描述、容纳体验与校准判断逐渐成为能力。</p>${button('practice','记录这一次看见')}<a class="text-link" href="#/becoming">连接觉知、觉察与重新选择 ↗</a></section></div>`;}

function library(){return `<div class="page-shell">${breadcrumbs([['文章与案例']])}${pageHead('READINGS & EXPLORATIONS','沿着一个问题，<br>继续深入。','思想的展开，生活中的练习，以及创造中的具体选择。')}<div class="library-list">${[['人道 · 创造自己','创造三阶：让选择成为经验','三层九要素、想象练习，以及自动模板的转化。','becoming','01'],['总论','三道总论','从求真出发，走向创造自己、改变世界与成就他人。','essay','02'],['王道 · 战略','布局：把未来带回现在','以布先手、据枢纽、留自由，改变下一局的起点。','layout','03'],['实践 · 情境示例','面对质疑，我如何回应？','在一个具体情境中，看见从体验到选择、从选择到成为的过程。','case','04']].map(([tag,title,desc,url,n])=>`<a class="library-item" href="#/${url}"><span class="library-index">${n}</span><div><span class="eyebrow">${tag}</span><h2>${title}</h2><p>${desc}</p></div>${arrow}</a>`).join('')}</div></div>`;}

function casePage(){return `<div class="page-shell">${breadcrumbs([['文章与案例','library'],['面对质疑，我如何回应？']])}${pageHead('PRACTICE / 情境示例','面对质疑，<br>我如何回应？','用一次创作中的反馈，走过看清、选择与成为。')}<div class="article-layout"><aside class="article-toc"><span class="eyebrow">阅读线索</span><p>觉察 → 接纳 → 选择</p>${link('awareness','练习觉察')}</aside><article class="prose"><p>你提交了一部作品。一位读者说：“这部分说服不了我。”你感到难堪，想立刻解释自己的意图，也担心这句话意味着整部作品都没有价值。</p><h2>看清：把体验分开。</h2><p>事实是：一位读者对某个部分提出质疑。身体的反应是胸口发紧，感受是难堪与担心。头脑加入的解释是：“如果他不认可，我就没有能力。”</p><p>你开始看见，急于辩解是在保护被认可的需要。你可以理解这个需要，同时给自己一点空间，重新阅读反馈。</p><h2>选择：我愿意成为谁？</h2><p>“我愿意成为忠于探索的创作者。”这个选择使你把注意力放回作品：批评具体指向哪里？有什么值得修正？哪些地方需要进一步讨论？</p><h2>成为：让选择进入一次回应。</h2><p>你先询问：“是哪一个推论让你觉得不够充分？”再把能够确认的问题写下来，安排一次修改。对于仍有分歧的部分，你说明自己的依据，保留继续讨论的空间。</p><p>修改之后，回看作品与自己的体验。你学到了什么？下一次面对反馈，能否更快辨认感受，也更自由地选择回应？</p><div class="question-callout"><span class="eyebrow">回到自己的生活</span><h3>最近哪一次质疑，仍在影响你？</h3>${button('practice','写下我的回应')}</div></article></div></div>`;}
function notFound(){return `<div class="page-shell">${pageHead('404 / 重新找到方向','这条路径尚未展开。','可以回到全图，找到正在寻找的思想。')}${button('map','回到三道全图')}</div>`;}

function route(){beginNavigation(main);cleanup();revealObserver?.disconnect();const raw=location.hash.slice(2)||'', [path,query]=raw.split('?'), params=new URLSearchParams(query||'');currentRoute=path;const isKnowing=path==='knowing'||path.startsWith('knowing/')||path==='concept/aspects';const isBecoming=path.startsWith('becoming')||['seven','consciousness','template','reality'].some(id=>path==='concept/'+id);document.body.classList.toggle('becoming-view',isBecoming);if(isBecoming&&path.startsWith('concept/'))params.set('layer',path.split('/')[1]);document.body.classList.toggle('reading',isKnowing||isBecoming||['essay','layout','case','becoming','becoming/practice','wang','wang/closing'].includes(path)||path.startsWith('concept/'));document.querySelector('meta[name=theme-color]').content=path?'#efeee8':'#181c1b';document.body.classList.toggle('home',!path);$('#mobile-nav').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','打开导航');document.body.classList.remove('menu-open');main.inert=false;$('.site-footer').inert=false;
 const views={'':home,start,knowing:knowingPage,acceptance:acceptancePage,map:()=>mapPage(params.get('focus')),tian:()=>overview('tian'),ren:()=>overview('ren'),wang:wangOverviewPage,'wang/closing':wangClosingPage,essay:essayPage,layout:layoutPage,practice:()=>practicePage(params.get('context')),awareness:awarenessPage,library,case:casePage,becoming:becomingPage,'becoming/practice':ninePracticePage};const elementId=path.startsWith('becoming/')?path.split('/')[1]:null;const selfId=path.startsWith('knowing/')?path.split('/')[1]:null;main.innerHTML=selfLayers.some(x=>x.id===selfId)?selfLayerPage(selfId):selfElements.some(x=>x.id===selfId)?selfElementPage(selfId):elements.some(e=>e.id===elementId)?becomingElementPage(elementId):['mechanism','cases'].includes(elementId)?becomingReadingPage(elementId):path.startsWith('concept/')?conceptPage(path.split('/')[1]):(views[path]||notFound)();
 const title=main.querySelector('h1')?.textContent.trim();document.title=path?`${title} — 三道哲学`:'三道哲学 — 看见真理，创造自己，改变世界';
 const parent=isKnowing||isBecoming||path==='acceptance'?'ren':path.startsWith('concept/')?(lookup(path.split('/')[1])?.path||'wang'):path==='layout'?'wang':path==='awareness'?'practice':path;
 document.querySelectorAll('.desktop-nav a,.map-nav').forEach(a=>{a.classList.toggle('active',a.hash===`#/${parent}`);if(a.hash===`#/${parent}`)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');revealObserver.unobserve(e.target);}}),{threshold:.08});main.querySelectorAll('.reveal').forEach(e=>revealObserver.observe(e));
 const disposers=[initTianVisuals(main)];if(!path)disposers.push(initHome());if(isKnowing)initKnowing();if(path==='becoming/practice')initNinePractice(params);else if(isBecoming)initBecoming(params);if($('#cosmos'))disposers.push(mountArt($('#cosmos')));if(path==='practice')initPractice();if(path==='map'){initMap();if(params.get('focus'))requestAnimationFrame(()=>$('#map-'+params.get('focus'))?.scrollIntoView({block:'center'}));}if(path==='layout')initLayoutTabs();if(path==='awareness')disposers.push(initAwareness());if(path)disposers.push(initReadingUI(main,path,elements,selfLayers,selfElements,[...indexed,...extraNodes]));cleanup=()=>disposers.forEach(fn=>fn());finishNavigation(main,path);initAcceptance(main,path,params);updateHeader();
}

function initMap(){document.querySelectorAll('[data-map-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-map-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});const filter=b.dataset.mapFilter;document.querySelectorAll('.atlas-column').forEach(c=>c.hidden=filter!=='all'&&c.dataset.path!==filter);$('.atlas').classList.toggle('single',filter!=='all');if(scrollY>$('.map-toolbar').offsetTop-90)$('.map-toolbar').scrollIntoView({block:'start',behavior:'instant'});});document.querySelectorAll('[data-expand]').forEach(b=>b.onclick=()=>document.querySelectorAll('.atlas-column:not([hidden]) details').forEach(d=>d.open=b.dataset.expand==='yes'));}
function initLayoutTabs(){const tabs=[...document.querySelectorAll('[data-layout-tab]')];function activate(b){tabs.forEach(x=>{const active=x===b;x.setAttribute('aria-selected',String(active));x.tabIndex=active?0:-1;$('#layout-'+x.dataset.layoutTab).hidden=!active;});}tabs.forEach((b,i)=>{b.onclick=()=>activate(b);b.onkeydown=e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?tabs[0]:e.key==='End'?tabs.at(-1):tabs[(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length];activate(next);next.focus();}};});}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('shown');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('shown'),3500);}
const recordKey='triatao.practice.v1';
function readRecord(){try{return JSON.parse(localStorage.getItem(recordKey)||'{}')}catch{return {}}}
function initPractice(){const form=$('#practice-form'),record=readRecord(),keys=['clarity','choice','action'];keys.forEach(k=>form.elements[k].value=record[k]||'');if(keys.some(k=>record[k]))$('#save-status').textContent='已恢复这台设备上的记录';
 let clearArmed=false;
 function values(){return Object.fromEntries(keys.map(k=>[k,form.elements[k].value]));}
 form.addEventListener('input',()=>{try{localStorage.setItem(recordKey,JSON.stringify({...values(),updatedAt:new Date().toISOString()}));$('#save-status').textContent='已自动保存在当前浏览器';}catch{$('#save-status').textContent='浏览器无法保存，请使用导出记录';}$('#practice-summary').hidden=true;$('#practice-validation').textContent='';clearArmed=false;$('#clear-practice').textContent='清空';});
 form.onsubmit=e=>{e.preventDefault();const v=values(),missing=keys.find(k=>!v[k].trim());if(missing){$('#practice-validation').textContent='请先为每一步写下一句话，再一起回看。';form.elements[missing].focus();return;}const box=$('#practice-summary');box.innerHTML=`<span class="eyebrow">把这一份选择，带回今天。</span>${keys.map((k,i)=>`<h3>${['看清','选择','成为'][i]}</h3><p>${esc(v[k]).replace(/\n/g,'<br>')}</p>`).join('')}<p class="micro">实践之后，再回来看看：我从体验与结果中，看见了什么？</p>`;box.hidden=false;box.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});};
 $('#clear-practice').onclick=()=>{if(!clearArmed){clearArmed=true;$('#clear-practice').textContent='确认清空？';toast('再次点击“确认清空”会删除当前记录。');return;}keys.forEach(k=>form.elements[k].value='');try{localStorage.removeItem(recordKey)}catch{}$('#save-status').textContent='当前记录已清空';$('#practice-summary').hidden=true;$('#practice-validation').textContent='';$('#clear-practice').textContent='清空';clearArmed=false;};
 $('#export-practice').onclick=()=>{const v=values();if(!keys.some(k=>v[k].trim())){toast('写下一句话后，就可以导出记录。');return;}const content=`三道哲学 · 日用三步\n${new Date().toLocaleDateString('zh-CN')}\n\n${keys.map((k,i)=>`${['看清','选择','成为'][i]}\n${v[k]}`).join('\n\n')}\n`;const url=URL.createObjectURL(new Blob(['\uFEFF'+content],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`三道哲学-日用记录-${new Date().toISOString().slice(0,10)}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('记录已导出。');};
}
function initAwareness(){let interval=null,remaining=60,deadline=0,paused=false;const b=$('#awareness-timer'),s=$('#timer-status'),c=$('#awareness-cue');function tick(){remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));s.textContent=`还剩 ${remaining} 秒`;if(remaining<=0){clearInterval(interval);interval=null;b.textContent='再观察一分钟 ↗';b.dataset.state='idle';s.textContent='观察完成，带着所见回到选择。';c.textContent='你注意到了什么？';$('.breathing-circle').classList.remove('running');remaining=60;}}b.onclick=()=>{if(b.dataset.state==='running'){remaining=Math.max(1,Math.ceil((deadline-Date.now())/1000));clearInterval(interval);interval=null;paused=true;b.dataset.state='paused';b.textContent='继续观察 ↗';s.textContent=`已暂停 · 剩余 ${remaining} 秒`;$('.breathing-circle').classList.remove('running');return;}deadline=Date.now()+remaining*1000;b.dataset.state='running';b.textContent='暂停观察 Ⅱ';s.textContent=`还剩 ${remaining} 秒`;c.textContent='留意感受，允许体验自然发生';$('.breathing-circle').classList.add('running');interval=setInterval(tick,250);};return()=>clearInterval(interval);}

